using FreshFoundation;
using System.Text.Json;
public static class R10Checks
{
    public static GameCatalog Catalog()=>new([
        new(GameCatalogKind.Weapon,1000,new(){["en"]="SYNTHETIC long weapon",["zh-CN"]="合成长武器"},"GreatSword",Origin:new("synthetic","synthetic"),EquipmentStats:new(BaseAttack:100,AffinityPercent:10,DefenseBonus:5,BaseSlotLevels:[3,1,0])),
        new(GameCatalogKind.Armor,1001,new(){["en"]="SYNTHETIC helm",["zh-CN"]="合成头甲"},"Head",Origin:new("synthetic","synthetic"),SkillRelations:[new(10,2)],EquipmentStats:new(BaseDefense:20,Resistances:new(2,-1,0,1,-2),BaseSlotLevels:[2,0,0])),
        new(GameCatalogKind.Skill,10,new(){["en"]="SYNTHETIC Focus",["zh-CN"]="合成集中"},Origin:new("synthetic","synthetic"),DeclaredMaximumSkillLevel:3),
        new(GameCatalogKind.Decoration,20,new(){["en"]="SYNTHETIC jewel",["zh-CN"]="合成珠"},Origin:new("synthetic","synthetic"),RequiredSlotLevel:2,SkillRelations:[new(10,1)])]);
    internal static int Run()
    {
        int failed=0;var cases=new List<object>();void Check(bool condition){if(!condition)throw new Exception("R10 assertion failed");}void Test(string name,Action a){try{a();cases.Add(new{name,status="PASS"});}catch(Exception e){failed++;cases.Add(new{name,status="FAIL",error=e.Message});}}
        var catalog=Catalog();var planner=new BuildPlanner(catalog);var weapon=new PlannedPiece(BuildPosition.Weapon,1000,[20,0,0]);var armor=new PlannedPiece(BuildPosition.Head,1001,[0,0,0]);
        Test("candidate gate related skill search and synthetic totals",()=>{Check(planner.Decorations("集中",3).Count==0);planner.ShowCandidates=true;Check(planner.Decorations("集中",3).Single().Id==20&&planner.Decorations("Focus",3).Single().Id==20&&planner.Decorations("20",1).Count==0);planner.Confirm(weapon);planner.Confirm(armor);var s=planner.Summarize();Check(s.Defense==25&&s.Resistances?.Fire==2&&s.Resistances.Water==-1&&s.Attack==100&&s.Affinity==10&&s.Skills.Single().Total==3&&!s.Partial);});
        Test("detached cancel virtual pair excess and conflict exclusion",()=>{string before=planner.ToJson();var draft=weapon with{Decorations=[0,20,0]};Check(before==planner.ToJson());planner.Confirm(draft);var s=planner.Summarize();Check(s.Partial&&s.Skills.Single().Total==2);planner.Confirm(weapon);planner.Confirm(new(BuildPosition.Talisman,null,[0,0,0],new([new(10,2),new(0,0)],[0,0,0])));var skill=planner.Summarize().Skills.Single();Check(skill.Total==5&&skill.Effective==3&&skill.Excess==2);});
        Test("portable roundtrip unresolved and failed load preserve plan",()=>{planner.Title="SYNTHETIC plan";string json=planner.ToJson();Check(!json.Contains("synthetic\"",StringComparison.Ordinal)&&!json.Contains("EquipmentStats")&&!json.Contains("Source")&&!json.Contains("SYNTHETIC Focus"));var copy=new BuildPlanner(catalog){ShowCandidates=true};copy.LoadJson(json);Check(copy.Summarize().Defense==25&&copy.Title==planner.Title);string previous=copy.ToJson();foreach(string bad in new[]{json.Replace("\"SchemaVersion\": 1","\"SchemaVersion\": 99"),json.Replace("\"Id\": 1000","\"Id\": -1"),json.Replace("\"Id\": 1000","\"Id\": 4294967296"),new string('x',1048577),"{\"Schema\":\"rise-offline-build\",\"SchemaVersion\":1,\"Title\":\"x\",\"Pieces\":[{\"Position\":0,\"Id\":1,\"Decorations\":[0,0,0]},{\"Position\":0,\"Id\":2,\"Decorations\":[0,0,0]}]}"}){bool rejected=false;try{copy.LoadJson(bad);}catch{rejected=true;}Check(rejected&&previous==copy.ToJson());}copy.Confirm(new(BuildPosition.Legs,999999,[0,0,0]));Check(copy.Summarize().Partial&&copy.Piece(BuildPosition.Legs)?.Id==999999);copy.ShowCandidates=false;Check(copy.Summarize().Defense is null&&copy.Piece(BuildPosition.Weapon)?.Id==1000);});
        Test("offline operations do not touch selected synthetic save",()=>{string folder=Path.Combine(Directory.GetCurrentDirectory(),"synthetic-r10-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);string file=Path.Combine(folder,"slot.bin");File.WriteAllBytes(file,WorkspaceSyntheticSamples.Slot());var w=new EditorWorkspace();w.Open(file);string digest=w.Document!.Digest;var bytes=w.Document.Structure.CopyPayload();var serialized=w.Document.SerializeUnchanged();planner.Confirm(new(BuildPosition.Head,null,[0,0,0]));planner.LoadJson(planner.ToJson());Check(w.StagedCount==0&&w.Document.Digest==digest&&bytes.SequenceEqual(w.Document.Structure.CopyPayload())&&serialized.SequenceEqual(w.Document.SerializeUnchanged()));var d=new DomainEditor(w);d.TransferItem(0,1,1);w.Undo();Check(w.StagedCount==0);});
        Test("admitted enriched resource loads nullable equipment metadata",()=>{var real=GameCatalog.LoadDirectory(Path.Combine(Directory.GetCurrentDirectory(),"data","mhrice"));Check(real.Entries.Count==7675&&real.Entries.Count(e=>e.Kind==GameCatalogKind.Weapon&&e.EquipmentStats is not null)==3953&&real.Entries.Count(e=>e.Kind==GameCatalogKind.Armor&&e.EquipmentStats is not null)==1560&&real.Entries.Count(e=>e.Kind==GameCatalogKind.Decoration&&e.SkillRelations is not null)==244);});
        File.WriteAllText("test-results-r10.json",JsonSerializer.Serialize(new{atUtc=DateTimeOffset.UtcNow,scope="Synthetic offline planning only",failed,cases},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine($"R10 cases={cases.Count}; failures={failed}");return failed==0?0:1;
    }
}
